import{_ as c,C as t,o,c as n,E as a,a2 as d}from"./chunks/framework.Bx6eOp9J.js";const f=JSON.parse('{"title":"同样是送审，两种错误不能混算","description":"","frontmatter":{"title":"同样是送审，两种错误不能混算","date":"2026-10-28","column":"open-source-engineering","category":"academic","article_type":"research-note","edition":"research-center","research_question":"送审指标合并不同参考类别时，会隐藏什么？","summary":"一次可重跑的指标复核发现：按论文叙述重建的输入，在固定版本函数中得到 0.0067，而结果表写为 0.0267。差异尚不能归因，但足以说明送审指标需要保留原始类别。","sources":["https://arxiv.org/html/2609.37457v1","https://github.com/vtavakkoli/veriweave-govern/tree/77cf503e6cfaf35bc9e0dc7f03faa6bc832d02ec","https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents"],"pageClass":"runtime-v6-article","item_id":"academic-metric-boundaries","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-28-academic-metric-boundaries-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-10-28-academic-metric-boundaries.md","filePath":"zh/engineering/2026-10-28-academic-metric-boundaries.md","lastUpdated":1793193092000}'),s={name:"zh/engineering/2026-10-28-academic-metric-boundaries.md"};function l(h,e,p,m,g,u){const r=t("ArticleCover"),i=t("ArticleTableScroll");return o(),n("div",null,[a(r,{image:"/assets/covers/daily-2026-10-28-academic-metric-boundaries-cover.png",kicker:"研究成果",title:"同样是送审，两种错误不能混算",summary:"一次可重跑的指标复核发现：按论文叙述重建的输入，在固定版本函数中得到 0.0067，而结果表写为 0.0267。差异尚不能归因，但足以说明送审指标需要保留原始类别。",version:"2026-10-28",languageHref:"/en/engineering/2026-10-28-academic-metric-boundaries",languageLabel:"English"}),a(i,{language:"zh"}),e[0]||(e[0]=d('<h1 id="同样是送审-两种错误不能混算" tabindex="-1">同样是送审，两种错误不能混算 <a class="header-anchor" href="#同样是送审-两种错误不能混算" aria-label="Permalink to &quot;同样是送审，两种错误不能混算&quot;">​</a></h1><p>本应允许的操作被送去人工审查，可能只是多了一次等待；本应拒绝的操作被送审，则改变了原本的拒绝决定。两者都停在“送审”，却不能因此被当作同一种错误。评估智能体权限时，除了最终决定，还应保留它替代了哪个正确类别。</p><p>我们沿一篇治理论文的数字做了一个小复核：把作者叙述重建为输入，运行作者公开的指标函数。下面的差异可复跑，但还不足以确定原实验究竟哪一项记录需要修订。</p><h2 id="一个送审结果-来自两种偏差" tabindex="-1">一个送审结果，来自两种偏差 <a class="header-anchor" href="#一个送审结果-来自两种偏差" aria-label="Permalink to &quot;一个送审结果，来自两种偏差&quot;">​</a></h2><p>VeriWeave Govern（智能体动作的运行时治理研究系统）的论文为误送审率给出了一个明确口径：参考答案是允许，系统输出却是送审，这类案例的数量除以全部案例数。论文在另一处描述模型比较中的四个错误：一次允许变为送审，三次拒绝变为送审；结果表列出的误送审率为 0.0267。<a href="https://arxiv.org/html/2609.37457v1" target="_blank" rel="noreferrer">论文公式 8、表 13 与第 5.4 节</a></p><p>这几个公开陈述可以形成一个有条件的算术问题。<strong>假定错误方向的叙述完整且正确</strong>，狭义分子应是一次；若把两类非送审答案全部计入分子，则是四次。相同的分母不能让这两个分子变成同一个指标。</p><table tabindex="0"><thead><tr><th>参考决定 → 输出决定</th><th style="text-align:right;">重建数量</th><th>按上述定义计入误送审</th></tr></thead><tbody><tr><td>允许 → 送审</td><td style="text-align:right;">1</td><td>是</td></tr><tr><td>拒绝 → 送审</td><td style="text-align:right;">3</td><td>否，应另列</td></tr><tr><td>正确决定 → 相同决定</td><td style="text-align:right;">146</td><td>否</td></tr></tbody></table><p>表中是基于论文叙述构造的内部复核输入，不是作者原始逐行预测，也不是新采集的任务数据。这里没有把送审当作实际执行；拒绝变为送审也不能直接等同于未授权操作已经发生。</p><h2 id="固定版本函数如何计数" tabindex="-1">固定版本函数如何计数 <a class="header-anchor" href="#固定版本函数如何计数" aria-label="Permalink to &quot;固定版本函数如何计数&quot;">​</a></h2><p>我们核验的<a href="https://github.com/vtavakkoli/veriweave-govern/blob/77cf503e6cfaf35bc9e0dc7f03faa6bc832d02ec/research/metrics.py" target="_blank" rel="noreferrer">代码版本</a>中，误送审函数只计入“允许变送审”，与公式中的口径一致。内部探针直接执行这个函数；用于解释差异的宽口径计数另行计算，未改写上游函数。</p><p>重建集合共 150 项。探针得到狭义误送审率 <code>1/150 = 0.0067</code>，宽口径为 <code>4/150 = 0.0267</code>。准确率与宏平均 F1（逐类计算后取平均的分类指标）分别为 <code>0.9733</code>、<code>0.9573</code>，与论文相应汇总值吻合。这种吻合只是内部一致性检查，不能恢复原始预测的案例归属。</p><p>还做了两个对照。按另一组叙述重建的确定性系统得到误送审率 <code>30/150 = 0.2000</code>。故意把所有输入都送审的反例则得到误放行率为零、准确率仅 <code>0.1333</code>。后者不是任何受测系统的成绩；它说明单独追求“没有误放行”，无法区分有效判别与把决定全部交给人工。</p><p>可下载<a href="/joinwell52/assets/evidence/2026-10-28-academic-metric-boundaries/metric-audit.zip">最小复核包</a>，解压后运行 <code>python audit.py</code>。包中保留上游函数、许可、明确标为重建的输入和预期输出。它只运行分类计数，不调用模型，也不启动作者的治理服务。</p><h2 id="差异成立-归因仍未完成" tabindex="-1">差异成立，归因仍未完成 <a class="header-anchor" href="#差异成立-归因仍未完成" aria-label="Permalink to &quot;差异成立，归因仍未完成&quot;">​</a></h2><p>公开<a href="https://github.com/vtavakkoli/veriweave-govern/blob/77cf503e6cfaf35bc9e0dc7f03faa6bc832d02ec/results/paper-2026/README.md" target="_blank" rel="noreferrer">论文结果清单</a>明确说明，汇总值由稿件转录，不替代原始预测与标注。我们检查的完整仓库目录树没有那次运行的逐行预测和已完成标注表。因此，这次检查不能判断是表格、错误方向叙述，还是历史运行采用的指标版本产生了差异；也不能据此改写模型排名。</p><p>论文、作者仓库与转录清单属于同一研究来源。它们互相对应，有助于追踪出处，却不是相互独立的实证验证。本次探针属于内部实验依据；没有取得第三方对原实验的独立复现。论文可访问、正式发表或经过同行评审，都不能自动补上这项缺口。</p><h2 id="给评估结果保留方向" tabindex="-1">给评估结果保留方向 <a class="header-anchor" href="#给评估结果保留方向" aria-label="Permalink to &quot;给评估结果保留方向&quot;">​</a></h2><p>建议在汇总值旁保留完整的三类混淆矩阵，即逐项显示“参考决定”和“输出决定”的交叉计数。误放行、允许变送审、拒绝变送审分别列出，并写清各自分母。若业务明确需要“所有额外送审”这一宽指标，可以使用它，但应给出新名称及定义，避免沿用狭义误送审率的标签。</p><p>这也呼应<a href="https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents" target="_blank" rel="noreferrer">智能体评估方法说明</a>对“执行轨迹”与“实际结果”的区分。该机构方法文档提供的是独立的评估背景，并没有复核本文发现的数字差异。</p><p>这项检查适用于具有允许、送审、拒绝三种结果的分类评估；只有两个结果的系统需要另定口径。它没有验证治理服务的安全性、人工审查效果或真实队列负担。要进一步解释这处差异，仍需要与稿件版本绑定的原始预测、标注和当时的计算函数。当前能够保留的判断是：<strong>先区分错误从哪里来，再讨论送审带来了多少成本。</strong></p>',20))])}const v=c(s,[["render",l]]);export{f as __pageData,v as default};
